TEXTS.it = {
  _name: "Italiano",
  title: "Emkay – un assistente vocale sul telefono o sul tablet che hai già",
  description: "Emkay trasforma un telefono, un tablet, una TV o un Raspberry Pi in un assistente vocale OpenVoiceOS completo: apri una pagina web e di' «Hey Emkay». Privacy fin dall'inizio, funziona con Home Assistant, niente da installare.",
  tag: "Il tuo telefono o tablet diventa un assistente vocale completo. Apri una pagina web, di' <b>«Hey Emkay»</b>: niente da installare, niente da configurare.",
  pills: "<li>Nessun account</li><li>La voce resta sul dispositivo</li><li>Nessuno ascolta</li><li>Open source</li>",
  open: "Apri Emkay",
  store: "Negozio di skill",
  note: "Alpha iniziale · libero e open source · basato su OpenVoiceOS",
  uses_h: "Usa quello che hai già",
  uses_lead: "Nessuno smart speaker da comprare, nessun app store, nessuna riga di comando. Va bene qualsiasi dispositivo con un browser e un microfono.",
  use_phone_h: "Il tuo telefono",
  use_phone_p: "Timer, sveglie, il meteo, musica e radio, risposte alle domande, ovunque tu sia.",
  use_tablet_h: "Un vecchio tablet in cucina",
  use_tablet_p: "Dai un nuovo lavoro al tablet nel cassetto: al muro o sul piano di lavoro, sempre in ascolto di «Hey Emkay», con il viso sullo schermo.",
  use_tv_h: "Una TV o un Raspberry Pi",
  use_tv_p: "Modalità kiosk: schermo intero, schermo sempre acceso. Di' <i class=\"say\">«schermo intero»</i> o <i class=\"say\">«tieni lo schermo acceso»</i> e lo fa.",
  use_home_h: "La tua casa smart",
  use_home_p: "Accendi le luci, abbassa le tapparelle, avvia una scena, con Home Assistant (vedi sotto).",
  privacy_h: "Privacy fin dall'inizio",
  privacy_lead: "Il riconoscimento vocale e la voce funzionano di default sul dispositivo: ciò che dici resta lì. Un piccolo segno accanto a ⚙ mostra sempre dove Emkay ascolta, parla e pensa, e diventa ambra se qualcosa va a un server.",
  priv_offline_h: "Vai offline",
  priv_offline_p: "Di' <i class=\"say\">«vai offline»</i> o <i class=\"say\">«attiva la modalità privacy»</i>: riconoscimento vocale e voce passano nel dispositivo, internet viene chiuso e un piccolo scudo sullo schermo lo mostra. Niente di quello che dici esce dal dispositivo. <i class=\"say\">«Vai online»</i> lo riapre.",
  priv_log_h: "Un registro di rete leggibile",
  priv_log_p: "Ogni servizio che Emkay contatta viene registrato sul dispositivo, per giorno e servizio: ⚙ → Guardian. Aprilo o scaricalo. Conserva dove e quando, mai cosa è stato detto.",
  priv_ask_h: "Basta chiedere",
  priv_ask_p: "<i class=\"say\">«Cosa hai mandato fuori oggi?»</i> – <i class=\"say\">«Chi sente quello che dico?»</i> – <i class=\"say\">«Sei online?»</i> Emkay risponde dal proprio registro e dalle impostazioni.",
  priv_local_h: "Sul dispositivo, di default",
  priv_local_p: "Il riconoscimento vocale Whisper (e modelli nazionali, come Røst per il danese) e le voci Piper funzionano nel browser stesso: è così che parte Emkay. Finché i loro modelli non sono scaricati la prima volta, subentrano i server di OpenVoiceOS, e il segno lo dice. Le tue impostazioni restano nella memoria del browser sul dispositivo.",
  works_h: "Cosa ottieni",
  w_ovos_h: "OpenVoiceOS, senza modifiche",
  w_ovos_p: "OVOS core con le skill e la pipeline predefinite dell'installer, la homescreen e il viso del Mark II, dal canale alpha.",
  w_wake_h: "«Hey Emkay»",
  w_wake_p: "La parola di attivazione di Emkay, e quella predefinita (c'è anche «Hey Mycroft»), gira nel browser, quindi ascolta senza toccare lo schermo.",
  w_ask_h: "Skill che fanno domande",
  w_ask_p: "«Metti una sveglia» – «per quando?» – «tra cinque minuti». Le domande di seguito funzionano, come su un dispositivo.",
  w_answers_h: "Risposte alle domande",
  w_answers_p: "«Qual è la capitale della Francia?»: Wikipedia e altre fonti, e una wiki offline per quando internet è chiuso.",
  w_panel_h: "Il pannello di controllo",
  w_panel_p: "Il pannello di controllo standard di OVOS: impostazioni, procedura guidata, backup, installazione di skill e plugin.",
  w_store_h: "Un negozio di skill",
  w_store_p: "<a href=\"https://store.emkay.ai/\">store.emkay.ai</a>: skill OVOS provate in Emkay, per categoria, nella tua lingua, installate con un tocco, o a voce: <i class=\"say\">«trova una skill per le ricette»</i>.",
  w_hw_h: "Il dispositivo come hardware",
  w_hw_p: "Volume, posizione, accensione, sensori (batteria, rete, schermo, movimento, luce) e la fotocamera.",
  w_kiosk_h: "Kiosk a voce",
  w_kiosk_p: "<i class=\"say\">«Schermo intero»</i>, <i class=\"say\">«tieni lo schermo acceso»</i>, <i class=\"say\">«installa come app»</i>.",
  langs: "Lingue: inglese, danese, tedesco, olandese, francese, spagnolo, italiano, portoghese (Portogallo e Brasile), catalano, galiziano e basco.",
  ha_h: "Funziona con Home Assistant",
  ha_lead: "Collega Emkay al tuo Home Assistant una volta, e al resto pensa lui: ⚙ → <b>Dove deve pensare Emkay?</b> → <b>Collega al mio Home Assistant</b>. Accedi sulla pagina di Home Assistant, senza token da scrivere.",
  ha_voice_h: "Luci e riscaldamento con la voce",
  ha_voice_p: "<i class=\"say\">«Spegni la luce delle scale»</i>: Assist di Home Assistant lo capisce, e sa da quale stanza l'hai chiesto.",
  ha_device_h: "Emkay in Home Assistant",
  ha_device_p: "Ogni Emkay è lì un dispositivo, con volume, ascolto attivo o no e «di'». Niente ascolto in camera da letto di notte? Un'automazione.",
  ha_brain_h: "Oppure lascia pensare Home Assistant",
  ha_brain_p: "Scegli Home Assistant come cervello di Emkay, ed Emkay è un satellite di Assist, con il volto sullo schermo.",
  ha_house_h: "Tutta la casa",
  ha_house_p: "Con Emkay Home, la casa e ogni Emkay arrivano da soli in Home Assistant.",
  ha_note: "In Home Assistant: l'<a href=\"https://github.com/andlo/ha-ovos-integration\">integrazione OpenVoiceOS</a>, gratuita e compatibile con qualsiasi OpenVoiceOS.",
  home_h: "Emkay Home – per tutta la casa",
  home_p: "Emkay Home è l'OpenVoiceOS della casa, e ogni Emkay al suo interno – telefono, tablet, PC o TV – diventa il suo satellite. Lo installi una volta su una macchina sempre accesa; poi apri la sua pagina, scegli lingua e password, e aggiungi ogni Emkay con un codice QR. <b>È facoltativo</b>: ogni Emkay funziona benissimo da solo, senza casa – Emkay Home li collega quando lo desideri.",
  home_btn: "Ottieni Emkay Home",
  home_rooms_h: "Lo stesso assistente in ogni stanza",
  home_rooms_p: "Un solo OpenVoiceOS con le skill di Emkay, e gli Emkay sono le sue orecchie, la sua voce e il suo volto. Installa una skill una volta, e ogni stanza ce l'ha.",
  home_speech_h: "La casa ascolta e parla",
  home_speech_p: "Su una macchina con un po' di potenza, la casa può ascoltare e parlare per tutti gli Emkay – meglio e più velocemente di ogni dispositivo, con una sola voce per tutta la casa. Oppure lascialo ai dispositivi.",
  home_private_h: "Privato, a casa tua",
  home_private_p: "La casa crea il proprio certificato e serve Emkay da sé – niente passa da internet o da emkay.ai. Un nuovo Emkay si aggiunge con un codice QR, mai per e-mail.",
  home_easy_h: "Una riga per installarlo",
  home_easy_p: "Su un Raspberry Pi, un vecchio PC o un container Proxmox. La pagina della casa ha il pannello di controllo di OpenVoiceOS nei colori di Emkay, e collega la casa a Home Assistant.",
  home_note: "Debian, Ubuntu, Linux Mint, Raspberry Pi OS, Fedora, Rocky, AlmaLinux, Arch, Manjaro, openSUSE e Alpine – l'installer aggiunge Docker se manca. Open source su <a href=\"https://github.com/emkay-voice/emkay-home\">GitHub</a>.",
  capsule_h: "Emkay Capsule – un corpo per il tuo telefono",
  capsule_p: "Un guscio stampabile in 3D che trasforma un telefono in un piccolo Emkay per il piano della cucina, ispirato al concept Mycroft Mark II del 2018. Per ora un concept – file e immagini sono pronti, non è ancora stampato nulla.",
  capsule_btn: "Scopri Emkay Capsule",
  dev_h: "Emkay Dev – Crea la tua skill",
  dev_p: "Emkay è OpenVoiceOS, quindi puoi insegnargli cose nuove. Su dev.emkay.ai passi da zero alla tua skill che ti risponde – in VS Code nel browser, con Emkay proprio accanto al tuo codice. Niente da installare, e gli stessi test dello store.",
  dev_btn: "Inizia su dev.emkay.ai",
  dev_tpl_h: "Parti da un modello",
  dev_tpl_p: "<b>Emkay: New skill</b> – scegli una skill semplice, un fornitore di letture o un altro tipo, dagli un nome, e hai una skill funzionante da modificare.",
  dev_run_h: "Parlale un secondo dopo",
  dev_run_p: "Emkay si apre accanto al tuo codice ed esegue la tua skill – di nuovo ogni volta che salvi. Scrivile e ascolta la risposta, con il log della tua skill subito sotto.",
  dev_test_h: "Gli stessi test dello store",
  dev_test_p: "Le frasi di test della tua skill nella vista Testing di VS Code: ✓ quando una frase arriva alla tua skill, ✗ con chi l'ha presa al suo posto – giudicato come fa lo store di Emkay.",
  dev_any_h: "Nel browser o sul tuo PC",
  dev_any_p: "vscode.dev, github.dev, Codespaces o VS Code sulla tua macchina – con app.emkay.ai o l'Emkay di casa tua. Il tuo Emkay di tutti i giorni non viene mai toccato.",
  dev_note: "È OpenVoiceOS dall'inizio alla fine: una skill fatta qui funziona su qualsiasi OpenVoiceOS – e può finire nello <a href=\"https://store.emkay.ai\">store di Emkay</a>. L'estensione è <a href=\"https://github.com/emkay-voice/vscode-emkay\">open source</a>.",
  f_dev: "Crea una skill",
  start_h: "Per iniziare",
  start_1: "Apri <a href=\"https://app.emkay.ai/\">app.emkay.ai</a>. Il primo avvio scarica OpenVoiceOS e richiede qualche minuto; poi è più veloce.",
  start_2: "Tocca lo schermo quando te lo chiede: i browser permettono audio e microfono solo dopo un tocco.",
  start_3: "Scegli <b>Configura</b> per lingua, voce e altro, o parti con le impostazioni predefinite: la lingua del dispositivo, riconoscimento vocale e voce sul dispositivo stesso, e «Hey Emkay».",
  start_4: "Di' <b>«Hey Emkay»</b>, tocca il viso o tocca ⌨ per scrivere. Tutto il resto è sotto ⚙.",
  start_5: "⚙ → <b>Installa come app</b> mette Emkay sulla tua schermata Home (su iPhone: Condividi → Aggiungi alla schermata Home).",
  what_h: "Cos'è",
  what_p1: "Emkay è <a href=\"https://openvoiceos.org\">OpenVoiceOS</a>, l'assistente vocale aperto e attento alla privacy, che gira interamente dentro una pagina web, con il viso del Mycroft Mark II come schermo. Skill, impostazioni e plugin sono quelli di qualsiasi dispositivo OpenVoiceOS.",
  what_p2: "«Emkay» è «MK» detto ad alta voce: un omaggio ai Mark I e Mark II di Mycroft.",
  f_source: "Codice sorgente",
  f_note: "Emkay è un progetto della comunità basato su OpenVoiceOS. Apache-2.0.",
  dialogues: [
    ["Hey Emkay, che ore sono?", "Sono le otto e dieci."],
    ["Hey Emkay, imposta un timer di 5 minuti", "Timer di cinque minuti impostato."],
    ["Hey Emkay, vai offline", "Sono offline. Niente di quello che dici esce dal dispositivo.", true],
    ["Hey Emkay, qual è la capitale della Francia?", "La capitale della Francia è Parigi."],
    ["Hey Emkay, vai online", "Sono di nuovo online.", false],
    ["Hey Emkay, accendi la luce in cucina", "La luce in cucina è accesa."],
  ],
};

