  w_kiosk_h: "Quiosque por voz",
  w_kiosk_p: "<i class=\"say\">“Tela cheia”</i>, <i class=\"say\">“mantenha a tela ligada”</i>, <i class=\"say\">“instale como app”</i>.",
  langs: "Idiomas: inglês, dinamarquês, alemão, holandês, francês, espanhol, italiano, português (Portugal e Brasil), catalão, galego e basco.",
  ha_h: "Funciona com o Home Assistant",
